import socket
import concurrent.futures
from datetime import datetime

COMMON_PORTS = {
 21: "FTP", 22: "SSH", 23: "Telnet", 25: "SMTP",
 53: "DNS", 80: "HTTP", 110: "POP3", 143: "IMAP",
 443: "HTTPS", 445: "SMB", 3306: "MySQL", 3389: "RDP",
 5432: "PostgreSQL", 6379: "Redis", 8080: "HTTP-Alt",
 8443: "HTTPS-Alt", 27017: "MongoDB"
}

def banner_grab(host: str, port: int, timeout: float = 2.0) -> str:
 try:
 with socket.create_connection((host, port), timeout=timeout) as s:
 s.settimeout(timeout)
 try:
 # Send HTTP request for web ports
 if port in (80, 8080):
 s.send(b"GET / HTTP/1.0\r\nHost: " + host.encode() + b"\r\n\r\n")
 banner = s.recv(1024).decode("utf-8", errors="replace").strip()
 return banner[:200] # first 200 chars
 except socket.timeout:
 return ""
 except Exception:
 return ""

def scan_port(host: str, port: int) -> dict | None:
 try:
 with socket.create_connection((host, port), timeout=1.0):
 service = COMMON_PORTS.get(port, "unknown")
 banner = banner_grab(host, port)
 return {"port": port, "service": service, "banner": banner}
 except (socket.timeout, ConnectionRefusedError, OSError):
 return None

def scan(host: str, ports: list[int] | None = None, max_workers: int = 100) -> list[dict]:
 if ports is None:
 ports = list(COMMON_PORTS.keys())
 print(f"Scanning {host} — {len(ports)} ports — started {datetime.now():%H:%M:%S}")
 open_ports = []
 with concurrent.futures.ThreadPoolExecutor(max_workers=max_workers) as ex:
 futures = {ex.submit(scan_port, host, p): p for p in ports}
 for f in concurrent.futures.as_completed(futures):
 result = f.result()
 if result:
 open_ports.append(result)
 print(f" OPEN {result['port']:5d}/tcp {result['service']:<15} {result['banner'][:60]}")
 return sorted(open_ports, key=lambda x: x["port"])

